// ---- shared helpers (same in every page node) ----
const BASE = 'https://n8n.rixgpt.com/webhook/invoices';
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const money = (n, cur) => (n === null || n === undefined || Number.isNaN(+n) ? '–' : (cur ? cur + ' ' : '') + Number(n).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
const stClass = (s) => ({ 'Auto-approved': 'st-ok', Approved: 'st-ok', 'Waiting for approval': 'st-wait', 'Needs review': 'st-bad', Rejected: 'st-bad', 'Not an invoice': 'st-info', 'Could not read': 'st-bad' }[s] || 'st-info');
const CSS = `*{box-sizing:border-box}body{margin:0;background:#f3f5f9;font:16px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:#1d2433}
.wrap{max-width:780px;margin:0 auto;padding:28px 16px 40px}.wide{max-width:1100px}
.brand{display:flex;align-items:center;gap:10px;font-weight:700;color:#0f2a4a;margin-bottom:18px}
.logo{width:34px;height:34px;border-radius:9px;background:#0f2a4a;color:#fff;display:grid;place-items:center;font-weight:800}
.pill{margin-left:auto;font-size:12px;font-weight:600;color:#8a5a00;background:#fff3d6;border:1px solid #f1d58f;padding:3px 10px;border-radius:99px}
.card{background:#fff;border:1px solid #e3e8ef;border-radius:14px;padding:24px;box-shadow:0 1px 2px rgba(16,24,40,.04);margin-bottom:16px}
h1{font-size:26px;line-height:1.25;margin:10px 0 8px;color:#0f2a4a}h2{font-size:17px;margin:0 0 12px;color:#0f2a4a}
p{margin:0 0 12px}.muted{color:#5b6576}.small{font-size:14px}
.score{display:inline-block;font-weight:700;padding:4px 12px;border-radius:99px;font-size:14px}
.hot{background:#ffe6e0;color:#b42318}.warm{background:#fff3d6;color:#8a5a00}.cold{background:#e8eef7;color:#344054}
.days{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px;margin-top:16px}
.day h3{font-size:14px;margin:0 0 8px;color:#344054}
.slot{display:block;text-align:center;padding:9px;margin-bottom:8px;border:1px solid #c9d3e3;border-radius:10px;color:#0f2a4a;text-decoration:none;font-weight:600;background:#fff}
.slot:hover{background:#0f2a4a;color:#fff;border-color:#0f2a4a}
.btn{display:inline-block;background:#0f2a4a;color:#fff;text-decoration:none;padding:11px 18px;border-radius:10px;font-weight:600;margin:4px 8px 4px 0}
.btn.alt{background:#fff;color:#0f2a4a;border:1px solid #c9d3e3}
.steps{list-style:none;padding:0;margin:0}.steps li{display:flex;gap:10px;padding:9px 0;border-top:1px solid #eef1f5}.steps li:first-child{border-top:0}
.ok{flex:none;width:22px;height:22px;border-radius:50%;background:#e3f6ea;color:#16794a;display:grid;place-items:center;font-size:13px;font-weight:800}
.ok.wait{background:#fff3d6;color:#8a5a00}.ok.no{background:#fde8e8;color:#b42318}
.big{font-size:20px;font-weight:700;color:#0f2a4a}
table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:9px 8px;border-top:1px solid #eef1f5;vertical-align:top}th{color:#5b6576;font-weight:600;border-top:0}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin-bottom:16px}
.kpi{background:#fff;border:1px solid #e3e8ef;border-radius:12px;padding:14px}.kpi b{display:block;font-size:26px;color:#0f2a4a}
a{color:#1d4ed8}footer{font-size:13px;color:#6b7485;text-align:center;margin-top:24px}
.st{display:inline-block;white-space:nowrap;font-weight:700;padding:4px 12px;border-radius:99px;font-size:14px}
.st-ok{background:#e3f6ea;color:#16794a}.st-wait{background:#fff3d6;color:#8a5a00}.st-bad{background:#fde8e8;color:#b42318}.st-info{background:#e8eef7;color:#344054}
.kv{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px 18px;margin-top:14px}.kv div{font-size:14px;color:#5b6576}.kv b{display:block;font-size:16px;color:#1d2433;font-weight:600}
.total{font-size:30px;font-weight:800;color:#0f2a4a}.num{text-align:right;white-space:nowrap}
.samples{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}.sample{border:1px solid #e3e8ef;border-radius:12px;padding:14px;background:#fafbfd}.sample h3{margin:0 0 4px;font-size:15px;color:#0f2a4a}.sample p{font-size:13px;color:#5b6576;margin:0 0 10px}
.sample form{display:inline}.sample button,.btn2{border:0;cursor:pointer;font:inherit;font-weight:600;font-size:14px;background:#0f2a4a;color:#fff;padding:8px 12px;border-radius:9px}.sample a{font-size:14px;margin-left:8px}
input[type=file]{display:block;width:100%;padding:14px;border:2px dashed #c9d3e3;border-radius:12px;background:#fafbfd;font:inherit;margin:8px 0 14px}
button.btn{border:0;cursor:pointer;font:inherit;font-weight:600;font-size:16px}.warnbox{background:#fff8e6;border:1px solid #f1d58f;border-radius:10px;padding:10px 14px;font-size:14px;color:#6b4e00;margin-top:12px}`;
const page = (title, body, wide) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>${CSS}</style></head><body><main class="wrap${wide ? ' wide' : ''}"><header class="brand"><span class="logo">H</span><span>Harborline Software · Accounts payable</span><span class="pill">Live demo</span></header>${body}<footer>Live demo built with n8n by Aqib ur Rehman · Harborline Software and the sample suppliers are fictional · please upload sample or fake invoices only.</footer></main></body></html>`;
const notFoundPage = () => page('Not found', `<div class="card"><h1>We couldn't find that invoice</h1><p class="muted">The link may be old (results are kept for 7 days). Read a new one below.</p><a class="btn" href="${BASE}">Read an invoice</a></div>`);
// ---- end shared helpers ----

// ---- sample invoices + a tiny PDF writer (so the demo has real PDFs to read) ----
const SAMPLES = {
  1: { file: 'northwind-INV-20431.pdf', title: 'Office supplies, £550.80', shows: 'Clean invoice over the £500 limit, so it waits for a manager', supplier: 'Northwind Office Supplies Ltd', addr: ['Unit 4, Riverside Trade Park', 'Leeds LS10 1AB, United Kingdom', 'VAT No. GB 284 7719 05'], no: 'INV-20431', date: '02 Oct 2026', due: '01 Nov 2026', po: 'PO-7781', cur: '£', items: [['A4 copier paper, box of 5 reams', 10, 4.5], ['Toner cartridge HP 59A (black)', 2, 62], ['Ergonomic desk chair, mesh back', 2, 145]], taxLabel: 'VAT 20%', taxRate: 0.2, terms: 'Payment due within 30 days by bank transfer.' },
  2: { file: 'brightline-CLD-7781.pdf', title: 'Cloud hosting, $400.00', shows: 'Clean invoice under $500, so it is approved automatically', supplier: 'Brightline Cloud Hosting Inc.', addr: ['500 Market Street, Suite 210', 'San Francisco, CA 94105, USA', 'EIN 84-2219034'], no: 'CLD-7781', date: '01 Oct 2026', due: '31 Oct 2026', po: '', cur: '$', items: [['Managed hosting, October 2026', 1, 240], ['Daily backups (30 days)', 1, 60], ['Priority support plan', 1, 100]], taxLabel: 'Sales tax 0%', taxRate: 0, terms: 'Charged to the card on file on the due date.' },
  3: { file: 'kestrel-INV-118.pdf', title: 'Marketing services, £4,224.00', shows: 'The subtotal on the invoice is wrong, so it is flagged for review', supplier: 'Kestrel Marketing Studio', addr: ['22 Harbour Lane', 'Bristol BS1 5TT, United Kingdom', 'VAT No. GB 991 2045 33'], no: 'INV-118', date: '08 Oct 2026', due: '22 Oct 2026', po: 'PO-7790', cur: '£', items: [['Social media content, October', 1, 1800], ['Paid ads management', 1, 950], ['Landing page copy (2 pages)', 2, 250]], printedSubtotal: 3520, taxLabel: 'VAT 20%', taxRate: 0.2, terms: 'Payment due within 14 days by bank transfer.' },
};
const pdfEsc = (s) => String(s).replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
const charW = (ch, bold) => ({ ' ': 278, '.': 278, ',': 278, '-': 333, '/': 278, ':': 278, '£': 556, '$': 556, '%': 889, '(': 333, ')': 333, '#': 556 }[ch] ?? (/[0-9]/.test(ch) ? 556 : /[A-Z]/.test(ch) ? (bold ? 722 : 667) : /[ijlft]/.test(ch) ? 260 : bold ? 590 : 540));
const textW = (s, size, bold) => [...String(s)].reduce((a, ch) => a + charW(ch, bold), 0) * size / 1000;
const fmt2 = (n) => Number(n).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
function makePdf(inv) {
  const ops = [];
  const text = (x, y, s, size = 10, bold = false, align = 'left', color = '0.11 0.14 0.2') => {
    const tx = align === 'right' ? x - textW(s, size, bold) : x;
    ops.push(`${color} rg BT /${bold ? 'F2' : 'F1'} ${size} Tf 1 0 0 1 ${tx.toFixed(2)} ${y} Tm (${pdfEsc(s)}) Tj ET`);
  };
  const rect = (x, y, w, h, color) => ops.push(`${color} rg ${x} ${y} ${w} ${h} re f`);
  const hline = (y) => ops.push(`0.86 0.88 0.92 RG 0.7 w 40 ${y} m 555 ${y} l S`);
  const gray = '0.36 0.4 0.46';
  rect(0, 772, 595, 70, '0.06 0.16 0.29');
  text(40, 800, inv.supplier, 18, true, 'left', '1 1 1');
  text(555, 800, 'INVOICE', 18, true, 'right', '1 1 1');
  inv.addr.forEach((l, i) => text(40, 748 - i * 13, l, 9, false, 'left', gray));
  [['Invoice no.', inv.no], ['Invoice date', inv.date], ['Due date', inv.due], ['PO number', inv.po || '-']].forEach(([k, v], i) => {
    text(450, 748 - i * 15, k, 9, false, 'right', gray);
    text(555, 748 - i * 15, v, 10, true, 'right');
  });
  text(40, 680, 'BILL TO', 9, true, 'left', gray);
  ['Harborline Software Ltd', '12 Quay Street, Bristol BS1 4DJ', 'accounts@harborline.example'].forEach((l, i) => text(40, 665 - i * 13, l, 10, i === 0));
  rect(40, 600, 515, 22, '0.94 0.95 0.97');
  text(48, 607, 'Description', 9, true);
  text(380, 607, 'Qty', 9, true, 'right');
  text(465, 607, 'Unit price', 9, true, 'right');
  text(547, 607, 'Amount', 9, true, 'right');
  let y = 582, sum = 0;
  for (const [d, q, p] of inv.items) {
    const amt = q * p; sum += amt;
    text(48, y, d, 10); text(380, y, String(q), 10, false, 'right'); text(465, y, inv.cur + fmt2(p), 10, false, 'right'); text(547, y, inv.cur + fmt2(amt), 10, false, 'right');
    hline(y - 8); y -= 24;
  }
  const sub = inv.printedSubtotal ?? sum, tax = Math.round(sub * inv.taxRate * 100) / 100, total = sub + tax;
  y -= 10;
  [['Subtotal', sub], [inv.taxLabel, tax]].forEach(([k, v]) => { text(465, y, k, 10, false, 'right', gray); text(547, y, inv.cur + fmt2(v), 10, false, 'right'); y -= 18; });
  y -= 8;
  rect(330, y - 8, 225, 26, '0.06 0.16 0.29');
  text(465, y, 'Total due', 11, true, 'right', '1 1 1'); text(547, y, inv.cur + fmt2(total), 12, true, 'right', '1 1 1');
  text(40, 150, 'Payment terms', 9, true, 'left', gray);
  text(40, 136, inv.terms, 10);
  text(40, 120, 'Bank: Harbour Demo Bank  |  Sort code 00-00-00  |  Account 12345678 (sample)', 9, false, 'left', gray);
  text(40, 60, 'Sample invoice made for a public n8n demo by Aqib ur Rehman. All companies and numbers are fictional.', 8, false, 'left', gray);
  const content = ops.join('\n');
  const objs = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>',
    `<< /Length ${content.length} >>\nstream\n${content}\nendstream`,
    `<< /Title (${pdfEsc(inv.supplier + ' ' + inv.no)}) /Producer (n8n demo) >>`,
  ];
  let out = '%PDF-1.4\n';
  const offs = [];
  objs.forEach((o, i) => { offs.push(out.length); out += `${i + 1} 0 obj\n${o}\nendobj\n`; });
  const xref = out.length;
  out += `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n` + offs.map((o) => String(o).padStart(10, '0') + ' 00000 n \n').join('');
  out += `trailer\n<< /Size ${objs.length + 1} /Root 1 0 R /Info 7 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return Buffer.from(out, 'latin1');
}
// ---- end samples ----

// Upload page: pick a PDF/photo of an invoice, or try one of the three sample invoices
const body = `<div class="card"><span class="st st-info">AI invoice reader</span>
<h1>Turn invoices and receipts into spreadsheet rows in seconds</h1>
<p class="muted">Upload a PDF or a photo. AI reads the supplier, dates, line items, tax and total, checks the maths, looks for duplicates and adds a row to Google Sheets. Anything over 500 goes to a manager for one-click approval.</p>
<form method="post" action="${BASE}" enctype="multipart/form-data">
<input type="file" name="file" accept=".pdf,.png,.jpg,.jpeg,.webp,application/pdf,image/*" required>
<button class="btn" type="submit">Read this invoice →</button>
</form>
<div class="warnbox">This is a public demo: please use a sample or a made-up invoice, not a real one with personal data. Files are not stored; the extracted fields are kept for 7 days.</div></div>
<div class="card"><h2>No invoice handy? Try a sample</h2><div class="samples">
${Object.entries(SAMPLES).map(([id, s]) => `<div class="sample"><h3>${esc(s.supplier)}</h3><p>${esc(s.title)} · ${esc(s.shows)}</p><form method="post" action="${BASE}" enctype="multipart/form-data"><input type="hidden" name="sample" value="${id}"><button type="submit">Read it</button></form><a href="${BASE}/sample?id=${id}">Download the PDF</a></div>`).join('')}
</div></div>
<div class="card"><h2>What happens when you press the button</h2><ol class="small" style="margin:0;padding-left:20px">
<li><b>Google Gemini</b> reads the PDF or photo (no templates, any layout) and returns the fields as structured data.</li>
<li>The workflow checks that the line items add up, that subtotal + tax = total, that required fields are there and that the invoice isn't a duplicate.</li>
<li>A row is added to <b>Google Sheets</b>. Clean invoices under 500 are approved automatically; bigger ones wait for a manager; anything odd is flagged for review.</li></ol></div>
<script>document.querySelectorAll('form').forEach(function(f){f.addEventListener('submit',function(){var b=f.querySelector('button');b.textContent='Reading…';b.style.opacity='.75';});});</script>`;
return [{ json: { html: page('AI invoice reader – Harborline Software', body) } }];

