// Prepare: take the uploaded file (or build a sample PDF), check type/size/daily limit, build the Gemini request
const started = Date.now();
const f = $json.body || {};
const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (!store.day || store.day.date !== today) store.day = { date: today, count: 0 };
const OK_TYPES = ['application/pdf', 'image/png', 'image/jpeg', 'image/webp'];
let problem = null, mime = null, b64 = null, fileName = null, source = 'Upload';
const sid = String(f.sample || '');
if (SAMPLES[sid]) {
  b64 = makePdf(SAMPLES[sid]).toString('base64'); mime = 'application/pdf'; fileName = SAMPLES[sid].file; source = 'Sample ' + sid;
