.sample form{display:inline}.sample button,.btn2{border:0;cursor:pointer;font:inherit;font-weight:600;font-size:14px;background:#0f2a4a;color:#fff;padding:8px 12px;border-radius:9px}.sample a{font-size:14px;margin-left:8px}
input[type=file]{display:block;width:100%;padding:14px;border:2px dashed #c9d3e3;border-radius:12px;background:#fafbfd;font:inherit;margin:8px 0 14px}
button.btn{border:0;cursor:pointer;font:inherit;font-weight:600;font-size:16px}.warnbox{background:#fff8e6;border:1px solid #f1d58f;border-radius:10px;padding:10px 14px;font-size:14px;color:#6b4e00;margin-top:12px}`;
const page = (title, body, wide) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>${CSS}</style></head><body><main class="wrap${wide ? ' wide' : ''}"><header class="brand"><span class="logo">H</span><span>Harborline Software · Accounts payable</span><span class="pill">Live demo</span></header>${body}<footer>Live demo built with n8n by Aqib ur Rehman · Harborline Software and the sample suppliers are fictional · please upload sample or fake invoices only.</footer></main></body></html>`;
const notFoundPage = () => page('Not found', `<div class="card"><h1>We couldn't find that invoice</h1><p class="muted">The link may be old (results are kept for 7 days). Read a new one below.</p><a class="btn" href="${BASE}">Read an invoice</a></div>`);
// ---- end shared helpers ----

// Owner view: every invoice read in the last 7 days, with status and totals
const inv = $getWorkflowStaticData('global').inv || [];
const count = (s) => inv.filter((r) => r.status === s).length;
const byCur = {};
inv.filter((r) => r.total !== null && !['Not an invoice', 'Could not read', 'Rejected'].includes(r.status)).forEach((r) => { byCur[r.currency || '?'] = (byCur[r.currency || '?'] || 0) + r.total; });
const totals = Object.entries(byCur).map(([c, v]) => money(v, c)).join(' · ') || '–';
const rows = inv.slice(0, 150).map((r) => `<tr><td>${new Date(r.createdAt).toLocaleString('en-GB', { timeZone: 'Europe/London', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' })}</td><td><b>${esc(r.supplier || '–')}</b><br><span class="muted small">${esc(r.source)} · ${esc(r.fileName)}</span></td><td>${esc(r.invoiceNumber || '–')}<br><span class="muted small">due ${esc(r.dueDate || '–')}</span></td><td class="num">${money(r.total, r.currency)}</td><td><span class="st ${stClass(r.status)}">${esc(r.status)}</span></td><td class="small">${esc(r.checks.filter((c) => c.level !== 'ok').map((c) => c.text).join('; ') || 'All checks passed')}</td><td>${r.row ? 'row ' + r.row : '–'}<br><a href="${BASE}/result?t=${r.token}" target="_blank">open</a></td></tr>`).join('');
const body = `<h1>Invoice register</h1><p class="muted">Owner view · last 7 days · ${new Date().toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'medium', timeStyle: 'short' })} UK</p>
<div class="kpis"><div class="kpi"><b>${inv.length}</b>Documents read</div><div class="kpi"><b>${count('Waiting for approval')}</b>Waiting for approval</div><div class="kpi"><b>${count('Needs review')}</b>Needs review</div><div class="kpi"><b>${count('Auto-approved') + count('Approved')}</b>Approved</div><div class="kpi"><b style="font-size:18px">${totals}</b>Value booked</div></div>
<div class="card" style="overflow-x:auto"><table><tr><th>Read</th><th>Supplier</th><th>Invoice</th><th class="num">Total</th><th>Status</th><th>Checks</th><th>Sheet</th></tr>${rows || '<tr><td colspan="7">Nothing yet.</td></tr>'}</table></div>
<p class="small muted">Full register: <a href="https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/edit" target="_blank">Google Sheets (Invoices tab)</a></p>`;
return [{ json: { html: page('Invoice register – owner view', body, true) } }];
